configuration.jsScript:
// ThingsBoard Transformation Node (script)
// Maps Alarm events + Customer/User Server Scope attributes to PushPayload

// 1. Extract subscription from Server Scope metadata (User, Customer, or Device fallback)
var rawSub = metadata.ss_push_subscription || metadata.cs_push_subscription || metadata.push_subscription;
var subscription = {};

if (rawSub) {
    try {
        subscription = (typeof rawSub === 'string') ? JSON.parse(rawSub) : rawSub;
    } catch (e) {
        subscription = {};
    }
}

// 2. Map Alarm Action to Severity
var severity = metadata.alarmSeverity || "CRITICAL";
if (metadata.action === "ClearAlarm") {
    severity = "INFO";
}

// 3. Process Temperature (Convert Kelvin to Celsius or Fahrenheit)
var formattedTemp = "";
var rawTemp = parseFloat(metadata.temp !== undefined ? metadata.temp : (msg && msg.temp));

if (!isNaN(rawTemp)) {
    var unitAttr = metadata.shared_temp_unit || metadata.ss_shared_temp_unit || "F";
    var isCelsius = unitAttr.toString().toUpperCase().trim().indexOf("C") === 0;

    var convertedTemp = isCelsius 
        ? rawTemp - 273.15 
        : (rawTemp - 273.15) * 1.8 + 32;

    var unitSymbol = isCelsius ? "°C" : "°F";
    formattedTemp = convertedTemp.toFixed(1) + " " + unitSymbol;
}

// 4. Build Notification Text
var deviceName = metadata.deviceName || metadata.ss_deviceName || "HUMID1 Sensor";
var alarmType = metadata.alarmType || "Environmental Alert";
var title = "";
var body = "";

if (metadata.action === "ClearAlarm") {
    title = "CLEARED: " + alarmType + " (" + deviceName + ")";
    body = alarmType + " condition returned to normal thresholds.";
} else {
    title = "[" + severity + "] " + alarmType + " - " + deviceName;

    var telemetryDetails = [];
    if (metadata.rh !== undefined) telemetryDetails.push("RH: " + metadata.rh + "%");
    if (formattedTemp) telemetryDetails.push("Temp: " + formattedTemp);
    if (metadata.battery !== undefined) telemetryDetails.push("Battery: " + metadata.battery + "%");

    body = "Alert triggered. Readings: " + (telemetryDetails.join(", ") || "N/A");
}

// 5. Construct PushPayload model matching FastAPI expectations
var newMsg = {
    subscription: subscription,
    title: title,
    body: body,
    severity: severity,
    deviceId: metadata.deviceId || "",
    deviceName: deviceName,
    url: "https://dash.humid1.com",
    tag: alarmType.toLowerCase().replace(/\s+/g, '-')
};

return {
    msg: newMsg,
    metadata: metadata,
    msgType: msgType
};

// Allow email if attribute is true or has not been explicitly set to false
var isEnabled = metadata.ss_push_enabled !== 'false' && metadata.ss_push_enabled !== false;
return isEnabled;
